/**
 * Minimal, dependency-free SHA-256 (FIPS 180-4) for the SyncPlay group gate.
 *
 * phlix-syncplay SPEC §4/§8.2 defines `password_hash` as the group-access
 * credential on the wire: the UNSALTED SHA-256 hex digest of the password —
 * a weak gate by design (the digest is replayable), NOT an identity proof,
 * which is why the server derives membership from the JWT subject instead
 * (SPEC §9). The server's `groupPasswordGate` accepts the canonical 64-char
 * lowercase hex digest with precedence over the legacy plaintext `password`
 * arm, so sending the hash keeps the secret off the WebSocket frame body.
 *
 * Why not `crypto.subtle.digest`? Three reasons, each fatal on its own:
 * the `GROUP_JOIN` frame is built SYNCHRONOUSLY inside `socket.onopen`
 * (`api/syncplay.ts`), and subtle is Promise-only; `crypto.subtle` is
 * absent in non-secure contexts (a media server on plain-http LAN — a
 * supported phlix deployment — would refuse to dial its own gate); and the
 * vitest/jsdom surface has no `subtle` at all, so the wire law would be
 * untestable. This mirrors the phlix-mobile-client `src/syncplay/sha256.ts`
 * primitive byte-for-byte in behaviour: pinned by the same NIST/Node
 * known-answer vectors in `syncplaySha256.test.ts`.
 *
 * @copyright 2026 Joe Huss <detain@interserver.net>
 * @license MIT
 */

/** SHA-256 round constants (first 32 bits of the fractional parts of the
 *  cube roots of the first 64 primes). */
const ROUND_CONSTANTS: readonly number[] = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
  0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
  0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
  0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
  0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
  0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
  0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

function rotateRight(value: number, bits: number): number {
  return ((value >>> bits) | (value << (32 - bits))) >>> 0;
}

/** Encode a string as UTF-8 bytes without relying on TextEncoder; surrogate
 *  pairs are handled via code points. */
function utf8Bytes(text: string): number[] {
  const bytes: number[] = [];
  for (let i = 0; i < text.length; i += 1) {
    const codePoint = text.codePointAt(i) as number;
    if (codePoint > 0xffff) {
      i += 1; // skip the trailing low surrogate
    }
    if (codePoint < 0x80) {
      bytes.push(codePoint);
    } else if (codePoint < 0x800) {
      bytes.push(0xc0 | (codePoint >>> 6), 0x80 | (codePoint & 0x3f));
    } else if (codePoint < 0x10000) {
      bytes.push(
        0xe0 | (codePoint >>> 12),
        0x80 | ((codePoint >>> 6) & 0x3f),
        0x80 | (codePoint & 0x3f)
      );
    } else {
      bytes.push(
        0xf0 | (codePoint >>> 18),
        0x80 | ((codePoint >>> 12) & 0x3f),
        0x80 | ((codePoint >>> 6) & 0x3f),
        0x80 | (codePoint & 0x3f)
      );
    }
  }
  return bytes;
}

/**
 * SHA-256 of a UTF-8 string, as 64-char lowercase hex.
 *
 * Pure function (Atomic Predictability): same input, same digest, no state.
 */
export function sha256Hex(input: string): string {
  const message = utf8Bytes(input);
  const bitLength = message.length * 8;

  message.push(0x80);
  while (message.length % 64 !== 56) {
    message.push(0x00);
  }
  // 64-bit big-endian length; JS numbers keep the high word exact below 2^53.
  const highLength = Math.floor(bitLength / 0x100000000);
  const lowLength = bitLength % 0x100000000;
  message.push(
    (highLength >>> 24) & 0xff,
    (highLength >>> 16) & 0xff,
    (highLength >>> 8) & 0xff,
    highLength & 0xff,
    (lowLength >>> 24) & 0xff,
    (lowLength >>> 16) & 0xff,
    (lowLength >>> 8) & 0xff,
    lowLength & 0xff
  );

  let h0 = 0x6a09e667;
  let h1 = 0xbb67ae85;
  let h2 = 0x3c6ef372;
  let h3 = 0xa54ff53a;
  let h4 = 0x510e527f;
  let h5 = 0x9b05688c;
  let h6 = 0x1f83d9ab;
  let h7 = 0x5be0cd19;

  const schedule = new Int32Array(64);

  for (let offset = 0; offset < message.length; offset += 64) {
    for (let t = 0; t < 16; t += 1) {
      const i = offset + t * 4;
      schedule[t] =
        ((message[i] << 24) |
          (message[i + 1] << 16) |
          (message[i + 2] << 8) |
          message[i + 3]) >>>
        0;
    }
    for (let t = 16; t < 64; t += 1) {
      const s0 =
        (rotateRight(schedule[t - 15], 7) ^
          rotateRight(schedule[t - 15], 18) ^
          (schedule[t - 15] >>> 3)) >>>
        0;
      const s1 =
        (rotateRight(schedule[t - 2], 17) ^
          rotateRight(schedule[t - 2], 19) ^
          (schedule[t - 2] >>> 10)) >>>
        0;
      schedule[t] =
        (schedule[t - 16] + s0 + schedule[t - 7] + s1) >>> 0;
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;
    let f = h5;
    let g = h6;
    let h = h7;

    for (let t = 0; t < 64; t += 1) {
      const S1 = (rotateRight(e, 6) ^ rotateRight(e, 11) ^ rotateRight(e, 25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const temp1 = (h + S1 + ch + ROUND_CONSTANTS[t] + schedule[t]) >>> 0;
      const S0 = (rotateRight(a, 2) ^ rotateRight(a, 13) ^ rotateRight(a, 22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const temp2 = (S0 + maj) >>> 0;

      h = g;
      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
    h5 = (h5 + f) >>> 0;
    h6 = (h6 + g) >>> 0;
    h7 = (h7 + h) >>> 0;
  }

  return [h0, h1, h2, h3, h4, h5, h6, h7]
    .map((word) => (word >>> 0).toString(16).padStart(8, '0'))
    .join('');
}

/**
 * Hash a SyncPlay group password into the SPEC §4 `password_hash` wire field.
 *
 * Guard clause (Early Exit): an empty password THROWS. `sha256Hex('')` is a
 * perfectly valid digest, but on the wire a hash-of-empty-string reads as a
 * SET (empty) group gate — so the omission decision ("no password → omit the
 * field") belongs to the callers and this throw is the fail-loud tripwire for
 * any future caller that forgets to.
 */
export function hashGroupPassword(password: string): string {
  if (password === '') {
    throw new Error(
      'hashGroupPassword: refusing to hash an empty password — omit the password_hash field instead'
    );
  }
  return sha256Hex(password);
}
